/* Build a later-story fixture by exercising the real rules, never by inventing flags. */
module.exports=function(){const R=require('../../nell-research'),N=require('../../nell-engine'),L=require('../../community-life-engine');let r=R.initial();for(const t of R.tasks){r=R.run(r,{type:'visit',id:t.id}).state;for(let i=0;i<3;i++)r=R.run(r,{type:'answer',id:t.id,step:i,choice:t.steps[i].answer,sequence:t.steps[i].order}).state;}let n=N.initial();while(!n.finished)n=N.run(n,n.chapter===4&&n.step===2?{type:'respond',text:'I want my family to know she was loved.'}:{type:'step',chapter:n.chapter,step:n.step},r).state;r=R.run(r,{type:'post',text:'I found her. Please come and meet the bears.'},n).state;let l=L.initial(),ctx={nell:n,mailPosted:true,storm:false};const run=a=>{l=L.run(l,a,ctx).state;};run({type:'arrive',place:'welcome'});for(let i=0;i<3;i++)run({type:'scene',id:'stay',step:i,choice:0});run({type:'rest'});run({type:'rest'});for(const id of ['family-reply','invitation']){run({type:'arrive',place:L.scenes.find(x=>x.id===id).place});for(let i=0;i<3;i++)run({type:'scene',id,step:i,choice:0});}run({type:'rest'});for(const id of ['family-boundary','family-welcome','family-hollow']){run({type:'arrive',place:L.scenes.find(x=>x.id===id).place});for(let i=0;i<3;i++)run({type:'scene',id,step:i,choice:0});}return{'honeybrook_nell_v1':n,'honeybrook_nell_research_v1':r,'honeybrook_community_life_v1':l};};
